import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.DJVIMu25.js";const b=JSON.parse('{"title":"Commands & Permissions","description":"","frontmatter":{"title":"Commands & Permissions"},"headers":[],"relativePath":"en/guides/commands.md","filePath":"en/guides/commands.md","lastUpdated":1786543805000}'),s={name:"en/guides/commands.md"};function m(i,e,c,n,r,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="commands-permissions" tabindex="-1">Commands &amp; Permissions <a class="header-anchor" href="#commands-permissions" aria-label="Permalink to &quot;Commands &amp; Permissions&quot;">​</a></h1><p>JoyMart exposes a small player command set plus an admin command set. All games and shop items are managed through GUIs, so the command surface stays minimal.</p><h2 id="player-commands-default-gamebox-alias-gb" tabindex="-1">Player Commands (default <code>/gamebox</code>, alias <code>/gb</code>) <a class="header-anchor" href="#player-commands-default-gamebox-alias-gb" aria-label="Permalink to &quot;Player Commands (default `/gamebox`, alias `/gb`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/gamebox</code></td><td><code>gamebox.use</code></td><td>Open the main menu</td></tr><tr><td><code>/gamebox &lt;subcommand&gt;</code></td><td><code>gamebox.play.&lt;id&gt;</code></td><td>Jump straight into a game (subcommands are defined in <a href="./configuration"><code>games.yml</code></a>)</td></tr><tr><td><code>/gamebox token</code></td><td><code>gamebox.use</code></td><td>View your token balance</td></tr><tr><td><code>/gamebox info</code></td><td><code>gamebox.use</code></td><td>View plugin info</td></tr><tr><td><code>/gamebox help</code></td><td><code>gamebox.use</code></td><td>View help</td></tr><tr><td><code>/gamebox accept [player]</code></td><td><code>gamebox.use</code></td><td>Accept a multiplayer invitation</td></tr><tr><td><code>/gamebox decline [player]</code></td><td><code>gamebox.use</code></td><td>Decline a multiplayer invitation</td></tr></tbody></table><h2 id="admin-commands-default-gameboxadmin-alias-gba" tabindex="-1">Admin Commands (default <code>/gameboxadmin</code>, alias <code>/gba</code>) <a class="header-anchor" href="#admin-commands-default-gameboxadmin-alias-gba" aria-label="Permalink to &quot;Admin Commands (default `/gameboxadmin`, alias `/gba`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/gba reload</code></td><td><code>gamebox.admin.reload</code></td><td>Reload all configs</td></tr><tr><td><code>/gba tokens &lt;player&gt; get</code></td><td><code>gamebox.admin.tokens</code></td><td>View a player&#39;s tokens</td></tr><tr><td><code>/gba tokens &lt;player&gt; set &lt;amount&gt;</code></td><td><code>gamebox.admin.tokens</code></td><td>Set a player&#39;s tokens</td></tr><tr><td><code>/gba tokens &lt;player&gt; give &lt;amount&gt;</code></td><td><code>gamebox.admin.tokens</code></td><td>Give tokens to a player</td></tr><tr><td><code>/gba tokens &lt;player&gt; take &lt;amount&gt;</code></td><td><code>gamebox.admin.tokens</code></td><td>Take tokens from a player</td></tr><tr><td><code>/gba games &lt;game&gt; &lt;enable|disable&gt;</code></td><td><code>gamebox.admin.games</code></td><td>Enable / disable a game</td></tr><tr><td><code>/gba games</code></td><td><code>gamebox.admin.games</code></td><td>Open the game management GUI (toggle games, edit lottery / slot machine prize pools)</td></tr><tr><td><code>/gba language</code></td><td><code>gamebox.admin.language</code></td><td>Check language file completeness</td></tr><tr><td><code>/gba migrate &lt;file|mysql&gt;</code></td><td><code>gamebox.admin.migrate</code></td><td>Migrate data between YAML / MySQL</td></tr><tr><td><code>/gba reset &lt;game&gt;</code></td><td><code>gamebox.admin.reset</code></td><td>Reset a game&#39;s high-score table</td></tr><tr><td><code>/gba shop</code></td><td><code>gamebox.admin.shop</code></td><td>Open the shop management GUI (list / unlist items)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Related pages</p><ul><li><a href="./configuration"><code>/gba games</code> and <code>/gba shop</code></a> open GUIs documented under Configuration Files.</li><li><a href="./../reference/storage"><code>/gba migrate</code></a> is documented in detail under Data Storage.</li></ul></div><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>gamebox.use</code></td><td>true</td><td>Use the <code>/gamebox</code> main command</td></tr><tr><td><code>gamebox.play.*</code></td><td>true</td><td>Play all games</td></tr><tr><td><code>gamebox.play.&lt;id&gt;</code></td><td>true</td><td>Play a specific game (e.g. <code>gamebox.play.2048</code>)</td></tr><tr><td><code>gamebox.gamegui.&lt;id&gt;</code></td><td>true</td><td>See a specific game&#39;s icon in the main menu</td></tr><tr><td><code>gamebox.admin.*</code></td><td>op</td><td>All admin permissions</td></tr><tr><td><code>gamebox.admin.shop</code></td><td>op</td><td>Manage shop items via GUI</td></tr><tr><td><code>gamebox.shop.&lt;custom&gt;</code></td><td>false</td><td>Permission to buy a specific shop item (defined per-item in <a href="./configuration"><code>tokenShop.yml</code></a>)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Auto-registration of permissions</p><p>Each game auto-registers its corresponding <code>gamebox.play.&lt;id&gt;</code> and <code>gamebox.gamegui.&lt;id&gt;</code> permissions (default true) when loaded. The <code>buyPermission</code> of shop items is <strong>not</strong> auto-registered — assign it with your permission plugin (e.g. LuckPerms).</p></div>',10)])])}const p=t(s,[["render",m]]);export{b as __pageData,p as default};
